import type { Block } from '@aws-sdk/client-textract';
import type {
  TextractBoundingBox,
  TextractLine,
  TextractPage,
  TextractWord,
} from 'generative-ai-use-cases';

// Textract synchronous APIs accept documents up to 10 MB
export const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024;

export type TextractFileType = 'jpeg' | 'png' | 'pdf' | 'tiff';

const EXTENSION_TO_TYPE: Record<string, TextractFileType> = {
  jpg: 'jpeg',
  jpeg: 'jpeg',
  png: 'png',
  pdf: 'pdf',
  tif: 'tiff',
  tiff: 'tiff',
};

// Keys are generated by the file upload flow (getFileUploadSignedUrl): `<uuid>/<filename>`
const FILE_KEY_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\/[^/\\]+$/i;

const hasControlChars = (s: string) =>
  [...s].some((c) => c.charCodeAt(0) < 0x20 || c.charCodeAt(0) === 0x7f);

export const isValidUploadedFileKey = (key: unknown): key is string =>
  typeof key === 'string' &&
  key.length <= 1024 &&
  FILE_KEY_PATTERN.test(key) &&
  !hasControlChars(key) &&
  !key.endsWith('/..') &&
  !key.endsWith('/.');

export const getTypeFromExtension = (
  fileName: string
): TextractFileType | null => {
  const idx = fileName.lastIndexOf('.');
  if (idx < 0) return null;
  return EXTENSION_TO_TYPE[fileName.slice(idx + 1).toLowerCase()] ?? null;
};

/** Detect the file type from the magic bytes. Returns null when unsupported. */
export const detectTypeFromMagicBytes = (
  bytes: Uint8Array
): TextractFileType | null => {
  const startsWith = (sig: number[]) =>
    bytes.length >= sig.length && sig.every((b, i) => bytes[i] === b);

  if (startsWith([0xff, 0xd8, 0xff])) return 'jpeg';
  if (startsWith([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))
    return 'png';
  if (startsWith([0x25, 0x50, 0x44, 0x46, 0x2d])) return 'pdf'; // %PDF-
  if (
    startsWith([0x49, 0x49, 0x2a, 0x00]) || // II*\0 (little endian)
    startsWith([0x4d, 0x4d, 0x00, 0x2a]) // MM\0* (big endian)
  )
    return 'tiff';
  return null;
};

export type ValidationResult =
  | { ok: true; fileType: TextractFileType }
  | { ok: false; message: string };

/** Validate extension, size and magic bytes (the extension and content must agree). */
export const validateDocument = (
  fileName: string,
  bytes: Uint8Array
): ValidationResult => {
  const extType = getTypeFromExtension(fileName);
  if (!extType) {
    return {
      ok: false,
      message:
        'Unsupported file extension. Supported: .jpg, .jpeg, .png, .pdf, .tif, .tiff',
    };
  }
  if (bytes.length === 0) {
    return { ok: false, message: 'The file is empty.' };
  }
  if (bytes.length > MAX_FILE_SIZE_BYTES) {
    return {
      ok: false,
      message: `The file is too large. The maximum size is ${MAX_FILE_SIZE_BYTES / 1024 / 1024} MB.`,
    };
  }
  const magicType = detectTypeFromMagicBytes(bytes);
  if (!magicType) {
    return {
      ok: false,
      message:
        'Unsupported file content. Supported: JPEG, PNG, PDF (one page), TIFF (one page)',
    };
  }
  if (magicType !== extType) {
    return {
      ok: false,
      message: 'The file content does not match its extension.',
    };
  }
  return { ok: true, fileType: magicType };
};

const toBoundingBox = (block: Block): TextractBoundingBox => ({
  left: block.Geometry?.BoundingBox?.Left ?? 0,
  top: block.Geometry?.BoundingBox?.Top ?? 0,
  width: block.Geometry?.BoundingBox?.Width ?? 0,
  height: block.Geometry?.BoundingBox?.Height ?? 0,
});

/**
 * Map Textract blocks (LINE / WORD) to the API response pages.
 * Bounding boxes are the normalized 0-1 ratios from Textract, unchanged.
 */
export const mapBlocksToPages = (blocks: Block[]): TextractPage[] => {
  const wordsById = new Map<string, TextractWord>();
  for (const block of blocks) {
    if (block.BlockType === 'WORD' && block.Id) {
      wordsById.set(block.Id, {
        id: block.Id,
        text: block.Text ?? '',
        confidence: block.Confidence ?? 0,
        boundingBox: toBoundingBox(block),
      });
    }
  }

  const pages = new Map<number, TextractLine[]>();
  for (const block of blocks) {
    if (block.BlockType !== 'LINE' || !block.Id) continue;
    const childIds =
      block.Relationships?.filter((r) => r.Type === 'CHILD').flatMap(
        (r) => r.Ids ?? []
      ) ?? [];
    const words = childIds
      .map((id) => wordsById.get(id))
      .filter((w): w is TextractWord => !!w);
    const line: TextractLine = {
      id: block.Id,
      text: block.Text ?? '',
      confidence: block.Confidence ?? 0,
      boundingBox: toBoundingBox(block),
      words,
    };
    const page = block.Page ?? 1;
    pages.set(page, [...(pages.get(page) ?? []), line]);
  }

  return [...pages.entries()]
    .sort(([a], [b]) => a - b)
    .map(([page, lines]) => ({ page, lines }));
};
